  "dcc_dialog_desc": "वह जानकारी भरें जो Opes Wealth को नहीं पता। सब कुछ वैकल्पिक है — खाली फ़ील्ड हाथ से भरने के लिए खाली पंक्तियों के रूप में प्रिंट होंगे।",
  "dcc_privacy_note": "PDF आपके ब्राउज़र में बनता है। आपकी प्रविष्टियाँ आपके अपने खाते में सहेजी जाती हैं (केवल आपको दिखती हैं) ताकि अगली बार फ़ॉर्म पहले से भरा मिले; उन्हें हटाने के लिए \"सहेजा गया विवरण मिटाएँ\" का उपयोग करें। संपत्ति तालिकाएँ कभी सहेजी नहीं जातीं और PDF पासवर्ड आपके ब्राउज़र से बाहर नहीं जाता।",
