  "av_estate_title": "विरासत हस्तांतरण: भुगतान के समय आयु के अनुसार छूट",
  "av_estate_intro": "फ्रांसीसी नियम जीवन बीमा प्रीमियम के साथ अलग व्यवहार करते हैं, यह इस पर निर्भर करता है कि हर प्रीमियम भरते समय बीमित व्यक्ति की आयु क्या थी। ये आँकड़े केवल संदर्भ के लिए हैं।",
  "av_estate_before70": "70 वर्ष की आयु से पहले भरे गए प्रीमियम (अनुच्छेद 990 I): प्रति लाभार्थी {amount} की छूट, बीमित व्यक्ति के सभी अनुबंधों को मिलाकर।",
  "av_estate_after70": "70 वर्ष की आयु के बाद भरे गए प्रीमियम (अनुच्छेद 757 B): कुल मिलाकर {amount} की एक छूट, जिसे सभी लाभार्थी साझा करते हैं, बीमित व्यक्ति के सभी अनुबंधों को मिलाकर। इसमें केवल प्रीमियम गिने जाते हैं; उनसे हुए लाभ इसके बाहर हैं।",
  "av_estate_no_bene": "ऊपर लाभार्थियों के नाम दर्ज करें, ताकि दिखे कि इन छूटों को कितने लोग साझा करते हैं।",
  "av_estate_arith_before": "नामित लाभार्थी: {count}। {per} x {count} = कुल {total} की छूट (प्रति लाभार्थी एक)।",
  "av_estate_arith_after": "नामित लाभार्थी: {count}। {overall} / {count} = बराबर बाँटने पर प्रत्येक को {share}। केवल उदाहरण के लिए: छूट कुल मिलाकर है, प्रति व्यक्ति नहीं।",
  "av_estate_disclaimer": "केवल जानकारी के लिए, कर सलाह नहीं। यह अनुबंध और कर निवास पर निर्भर करता है (UAE के निवासियों के साथ अलग व्यवहार होता है)। मौजूदा नियम जाँचें। आँकड़े {asOf} तक के हैं। यहाँ कुछ भी दावा नहीं किया जाता और कोई कर राशि नहीं निकाली जाती।",
